{"code": "def run(inputs: dict) -> dict:
    import csv
    import io

    # 1. Извлекаем денежные эквиваленты
    cash_metrics = inputs.get("ExtractedMetric", [])
    cash_2024 = None
    cash_2025 = None

    for metric in cash_metrics:
        if metric.get("concept") != "CASH_EQUIVALENTS":
            continue
        period = metric.get("period_ref")
        value = metric["scalar_fact"]["value"]
        unit = metric["scalar_fact"]["unit"]

        if unit != "млн. руб.":
            raise ValueError(f"Ожидалась единица 'млн. руб.', получена '{unit}'")

        if period == "31.12.2024":
            if cash_2024 is not None:
                # Дубликат — игнорируем, берём первый
                continue
            cash_2024 = value
        elif period == "31.12.2025":
            if cash_2025 is not None:
                continue
            cash_2025 = value

    if cash_2024 is None:
        raise ValueError("Не найден CASH_EQUIVALENTS за 31.12.2024")
    if cash_2025 is None:
        raise ValueError("Не найден CASH_EQUIVALENTS за 31.12.2025")

    # 2. Извлекаем цены Brent из CSV
    brent_artifacts = inputs.get("dyn:brent_csv", [])
    if not brent_artifacts:
        raise ValueError("CSV-файл с ценами Brent не предоставлен")

    csv_text = brent_artifacts[0]["payload"]["text"]
    reader = csv.DictReader(io.StringIO(csv_text))

    brent_2024 = None
    brent_2025 = None

    for row in reader:
        date_str = row.get("Date", "").strip()
        price_str = row.get("Price", "").strip()
        if not date_str or not price_str:
            continue
        try:
            year = int(date_str.split("-")[0])
            price = float(price_str)
        except (ValueError, IndexError):
            continue

        if year == 2024:
            brent_2024 = price
        elif year == 2025:
            brent_2025 = price

    if brent_2024 is None:
        raise ValueError("Не найдена цена Brent за 2024 год в CSV")
    if brent_2025 is None:
        raise ValueError("Не найдена цена Brent за 2025 год в CSV")

    # 3. Расчёт изменений
    cash_change_pct = ((cash_2025 - cash_2024) / cash_2024) * 100.0
    brent_change_pct = ((brent_2025 - brent_2024) / brent_2024) * 100.0

    return {
        "cash_equivalents_2024": cash_2024,
        "cash_equivalents_2025": cash_2025,
        "cash_change_pct": cash_change_pct,
        "brent_2024": brent_2024,
        "brent_2025": brent_2025,
        "brent_change_pct": brent_change_pct,
    }
", "example_inputs": {"ExtractedMetric": [  ], "dyn:brent_csv": [  ]}}
